#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// 128 x 64 pixels, on the I2C bus (Wire), no reset pin (-1).
Adafruit_SSD1306 display(128, 64, &Wire, -1);

int ballX = 10;   // where the ball is
int stepX = 3;    // how far it moves each time

void setup() {
  Serial.begin(9600);
  // SSD1306_SWITCHCAPVCC: the display makes its own high voltage inside.
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("OLED not found. Check the wiring and the address.");
    while (true) { }   // stop here
  }
}

void loop() {
  display.clearDisplay();

  display.setTextSize(2);                 // twice the normal size
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(4, 4);
  display.print("VSA Sim");

  display.drawRect(0, 28, 128, 36, SSD1306_WHITE);   // a frame
  display.fillCircle(ballX, 46, 6, SSD1306_WHITE);   // the ball

  display.display();   // nothing shows until this is called

  // Move the ball and bounce it off the sides of the frame.
  ballX = ballX + stepX;
  if (ballX < 8 || ballX > 119) {
    stepX = -stepX;
    Serial.print("The ball bounced at x = ");   // print a line in the Serial Monitor
    Serial.println(ballX);
  }
  delay(20);
}

/*
  Push Button and LED
  Lights the LED while the push button is pressed.

  The button pin uses the Arduino Nano's own pull-up resistor (INPUT_PULLUP),
  so no extra resistor is needed for the button. The pin reads HIGH when
  the button is released and LOW when it is pressed.
  In VSA Simulator, press and hold the button with the mouse while
  simulating.

  The circuit:
  - Push button: one side -> pin 2, other side -> GND
  - LED: pin 13 -> 220 ohm resistor -> LED anode, LED cathode -> GND

  The program also prints messages in the Serial Monitor, to show how a program can print text.

  You can modify this code and save it with another file name to simulate in
  VSA Simulator.

  Written on 26 September 2026 by Prof. Dattaraj S. Vidyasagar
  Modified on 23 October 2026 by Prof. Yash D. Vidyasagar

  This example code is in the public domain.
  For a great collection of example codes to simulate on VSA Simulator,
  visit: https://github.com/dsvakola/VSA-Simulator
  Or visit our official website: https://vsa.edu.in/
  To check our collection of useful software, visit: https://github.com/dsvakola/software
*/

const int buttonPin = 2;    // the push button
const int ledPin = 13;      // the LED (also the built-in LED)
int lastState = HIGH;       // the last button state, so a message is printed only when it changes

void setup() {
  pinMode(buttonPin, INPUT_PULLUP);   // HIGH when released, LOW when pressed
  pinMode(ledPin, OUTPUT);
  Serial.begin(9600);   // open the serial port so the program can print messages
}

void loop() {
  // Read the button. LOW means it is pressed (it connects the pin to GND).
  int buttonState = digitalRead(buttonPin);

  if (buttonState == LOW) {
    digitalWrite(ledPin, HIGH);   // pressed: LED on
  } else {
    digitalWrite(ledPin, LOW);    // released: LED off
  }

  if (buttonState != lastState) {   // the state changed: print it once
    Serial.println(buttonState == LOW ? "Button pressed: LED on" : "Button released: LED off");
    lastState = buttonState;
  }
}

/*
  Fading LED
  Makes an LED slowly brighten and dim using PWM (analogWrite).

  analogWrite() switches the pin on and off very fast. The longer it stays
  on in each cycle, the brighter the LED looks. The value goes from 0
  (always off) to 255 (always on).
  Only the pins marked with ~ on the board can do this: 3, 5, 6, 9, 10, 11.

  The circuit:
  - Pin 9 -> 220 ohm resistor -> LED anode (long leg)
  - LED cathode (short leg) -> GND

  The program also prints messages in the Serial Monitor, to show how a program can print text.

  You can modify this code and save it with another file name to simulate in
  VSA Simulator.

  Written on 04 October 2026 by Prof. Dattaraj S. Vidyasagar
  Modified on 03 November 2026 by Prof. Yash D. Vidyasagar

  This example code is in the public domain.
  For a great collection of example codes to simulate on VSA Simulator,
  visit: https://github.com/dsvakola/VSA-Simulator
  Or visit our official website: https://vsa.edu.in/
  To check our collection of useful software, visit: https://github.com/dsvakola/software
*/

const int ledPin = 9;     // a PWM pin (marked ~ on the board)
int brightness = 0;       // how bright the LED is now (0 to 255)
int fadeAmount = 5;       // how much to change it each time

void setup() {
  pinMode(ledPin, OUTPUT);
  Serial.begin(9600);   // open the serial port so the program can print messages
}

void loop() {
  analogWrite(ledPin, brightness);   // set the brightness

  // Change the brightness for the next time round the loop.
  brightness = brightness + fadeAmount;

  // At either end, turn round and fade the other way.
  if (brightness <= 0 || brightness >= 255) {
    fadeAmount = -fadeAmount;
    Serial.print("Brightness ");   // print a line in the Serial Monitor
    Serial.print(brightness);
    Serial.println(fadeAmount > 0 ? ": getting brighter" : ": getting dimmer");
  }

  delay(30);   // a short wait so the fading can be seen
}

/*
