const int potPin = A0;

void setup() {
  // Start the serial connection at 9600 bits per second.
  Serial.begin(9600);
}

void loop() {
  int value = analogRead(potPin);           // 0 to 1023
  float voltage = value * (5.0 / 1023.0);   // turn it back into volts

  Serial.print("Value: ");
