*/

#ifndef F_CPU
#define F_CPU 16000000UL      // the chip runs from a 16 MHz crystal
#endif
#include <avr/io.h>
#include <util/delay.h>

// ---- serial port (UART): 9600 baud -------------------------------------
#define BAUD_REG ((F_CPU / 16 / 9600) - 1)      // 103 for 16 MHz

static void uart_init(void)
{
    UBRRH = (uint8_t)(BAUD_REG >> 8);
    UBRRL = (uint8_t)BAUD_REG;
    UCSRB = (1 << RXEN) | (1 << TXEN);      // switch the receiver and transmitter on
    UCSRC = (1 << URSEL) | (1 << UCSZ1) | (1 << UCSZ0);   // 8 data bits, no parity, 1 stop bit
}

static void uart_putc(char c)
{
    while (!(UCSRA & (1 << UDRE)))
        ;                                         // wait until the transmit register is free
    UDR = c;
}

__attribute__((unused)) static void uart_puts(const char *s)
{
    while (*s)
        uart_putc(*s++);
}

__attribute__((unused)) static void uart_putnum(long n)                   // prints a whole number
{
    char buf[12];
    int i = 0;
    if (n < 0) { uart_putc('-'); n = -n; }
    if (n == 0) buf[i++] = '0';
    while (n > 0) { buf[i++] = '0' + (n % 10); n /= 10; }
    while (i > 0) uart_putc(buf[--i]);
}

int main(void)
{
    uint16_t counter = 0;

    uart_init();                                    // start the serial port at 9600 baud
    uart_puts("Hello from the ATmega8!\r\n");

    while (1)
    {
        // Wait one second, but look for typed characters every 10 ms.
        for (uint8_t i = 0; i < 100; i++)
        {
            if (UCSRA & (1 << RXC))                // a character was typed
            {
                char c = UDR;
                uart_puts("You typed: ");
                uart_putc(c);
                uart_puts("\r\n");
            }
            _delay_ms(10);
        }

        uart_puts("Count: ");
        uart_putnum(counter);
        uart_puts("\r\n");
        counter++;
    }
}

/*
  Push Button and LED
  Lights the LED while the push button is pressed.

  The button pin uses the chip's own pull-up resistor (INPUT_PULLUP),
  so no extra resistor is needed for the button. The pin reads HIGH
  when the button is released and LOW when it is pressed.
  In VSA Simulator, press and hold the button with the mouse.

  The circuit:
  - Push button: one side -> PD2, other side -> GND
  - LED: PB0 -> 220 ohm resistor -> LED anode, LED cathode -> GND

  The program also prints messages in the Serial Monitor, to show how a program can print text.

  You can modify this code and save it with another file name to simulate in
  VSA Simulator.

  Written on 16 October 2026 by Prof. Dattaraj S. Vidyasagar
  Modified on 30 October 2026 by Prof. Yash D. Vidyasagar

  This example code is in the public domain.
  For a great collection of example codes to simulate on VSA Simulator,
  visit: https://github.com/dsvakola/VSA-Simulator
  Or visit our official website: https://vsa.edu.in/
  To check our collection of useful software, visit: https://github.com/dsvakola/software
*/

const int buttonPin = PIN_PD2;   // the push button (PD2)
const int ledPin = PIN_PB0;      // the LED (PB0)
int lastState = HIGH;          // the last button state, so a message is printed only when it changes

void setup() {
  pinMode(buttonPin, INPUT_PULLUP);   // HIGH when released, LOW when pressed
  pinMode(ledPin, OUTPUT);
  Serial.begin(9600);                 // open the serial port so the program can print messages
}

void loop() {
  // LOW means the button is pressed (it connects the pin to GND).
  int state = digitalRead(buttonPin);
  if (state == LOW) {
    digitalWrite(ledPin, HIGH);   // pressed: LED on
  } else {
    digitalWrite(ledPin, LOW);    // released: LED off
  }

  if (state != lastState) {       // the state changed: print it once
    Serial.println(state == LOW ? "Button pressed: LED on" : "Button released: LED off");
    lastState = state;
  }
}

/*
  Fade
  Fades an LED smoothly up and down with PWM (analogWrite).

  Only some pins can do PWM (pulse width modulation). PB3 is one of them.
  The LED gets brighter as the pulses get longer.

  The circuit:
  - PB3 -> 220 ohm resistor -> LED anode, LED cathode -> GND

  The program also prints messages in the Serial Monitor, to show how a program can print text.

  You can modify this code and save it with another file name to simulate in
  VSA Simulator.

