const int ldrPin = A0;   // between the LDR and the 10 k resistor
const int ledPin = PIN_PB0;   // the LED
const int darkLevel = 300;  // below this reading we call it "dark"

void setup() {
  pinMode(ledPin, OUTPUT);
  Serial.begin(9600);
}

