  To check our collection of useful software, visit: https://github.com/dsvakola/software
*/

#ifndef F_CPU
#define F_CPU 16000000UL      // the chip runs from a 16 MHz crystal
#endif
#include <avr/io.h>
#include <util/delay.h>

// ---- serial port (UART): 9600 baud -------------------------------------
#define BAUD_REG ((F_CPU / 16 / 9600) - 1)      // 103 for 16 MHz

static void uart_init(void)
{
    UBRRH = (uint8_t)(BAUD_REG >> 8);
    UBRRL = (uint8_t)BAUD_REG;
    UCSRB = (1 << RXEN) | (1 << TXEN);      // switch the receiver and transmitter on
    UCSRC = (1 << URSEL) | (1 << UCSZ1) | (1 << UCSZ0);   // 8 data bits, no parity, 1 stop bit
}

static void uart_putc(char c)
{
    while (!(UCSRA & (1 << UDRE)))
        ;                                         // wait until the transmit register is free
    UDR = c;
}

__attribute__((unused)) static void uart_puts(const char *s)
{
    while (*s)
        uart_putc(*s++);
}

__attribute__((unused)) static void uart_putnum(long n)                   // prints a whole number
{
    char buf[12];
    int i = 0;
    if (n < 0) { uart_putc('-'); n = -n; }
    if (n == 0) buf[i++] = '0';
    while (n > 0) { buf[i++] = '0' + (n % 10); n /= 10; }
    while (i > 0) uart_putc(buf[--i]);
}
#include <stdlib.h>

#define LCD_ADDRESS 0x27            // the I2C address of the backpack

// Bits of the backpack: P0 = RS, P1 = RW, P2 = E, P3 = backlight, P4..P7 = D4..D7.
#define BACKLIGHT 0x08
#define ENABLE    0x04
#define RS        0x01

// ---- TWI (I2C) master ------------------------------------------------------
static void twi_init(void)
{
    TWSR = 0;                       // prescaler 1
    TWBR = 72;                      // 100 kHz at 16 MHz
}

static void twi_start(uint8_t address)
{
    TWCR = (1 << TWINT) | (1 << TWSTA) | (1 << TWEN);    // send START
    while (!(TWCR & (1 << TWINT)))
        ;
    TWDR = address << 1;                                  // address + write bit (0)
    TWCR = (1 << TWINT) | (1 << TWEN);
    while (!(TWCR & (1 << TWINT)))
        ;
}

static void twi_write(uint8_t data)
{
    TWDR = data;
    TWCR = (1 << TWINT) | (1 << TWEN);
    while (!(TWCR & (1 << TWINT)))
        ;
}

static void twi_stop(void)
{
    TWCR = (1 << TWINT) | (1 << TWSTO) | (1 << TWEN);    // send STOP
}

// ---- LCD ------------------------------------------------------------------
// Sends 4 bits and pulses the E line so the LCD reads them.
static void send_nibble(uint8_t nibble, uint8_t mode)
{
    uint8_t data = (nibble << 4) | BACKLIGHT | mode;
    twi_start(LCD_ADDRESS);
    twi_write(data | ENABLE);
    twi_write(data & ~ENABLE);
    twi_stop();
    _delay_us(100);
}

static void send_byte(uint8_t value, uint8_t mode)
{
    send_nibble(value >> 4, mode);          // high half first
    send_nibble(value & 0x0F, mode);        // then the low half
}

static void lcd_command(uint8_t c) { send_byte(c, 0); }
static void lcd_char(char c)       { send_byte(c, RS); }

static void lcd_print(const char *text)
{
    while (*text)
        lcd_char(*text++);
}

static void lcd_init(void)
{
    _delay_ms(50);
    send_nibble(0x03, 0);                   // the start-up sequence from the LCD data sheet
    _delay_ms(5);
    send_nibble(0x03, 0);
    send_nibble(0x03, 0);
    send_nibble(0x02, 0);                   // switch to 4-bit mode
    lcd_command(0x28);                      // 4-bit, 2 lines
    lcd_command(0x0C);                      // display on, cursor off
    lcd_command(0x06);                      // cursor moves right
    lcd_command(0x01);                      // clear the screen
    _delay_ms(3);
}

int main(void)
{
    char text[8];
    uint16_t seconds = 0;

    uart_init();                            // start the serial port so the program can print
    twi_init();
    lcd_init();
    lcd_command(0x80);                      // first line, first column
    lcd_print("VSA Simulator");

    while (1)
    {
        lcd_command(0xC0);                  // second line, first column
        lcd_print("Seconds: ");
        itoa(seconds, text, 10);            // number -> text
        lcd_print(text);
        uart_puts("Seconds: ");             // print the same number in the Serial Monitor
        uart_putnum(seconds);
        uart_puts("\r\n");
        _delay_ms(1000);
        seconds++;
    }
}

